import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import './Community.css';

const HeartIcon = ({ filled }) => (
  <svg width="15" height="15" viewBox="0 0 24 24" fill={filled ? 'currentColor' : 'none'} stroke="currentColor" strokeWidth="2">
    <path d="M20.84 4.61a5.5 5.5 0 0 0-7.78 0L12 5.67l-1.06-1.06a5.5 5.5 0 0 0-7.78 7.78l1.06 1.06L12 21.23l7.78-7.78 1.06-1.06a5.5 5.5 0 0 0 0-7.78z"/>
  </svg>
);
const BookmarkIcon = () => (
  <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
    <path d="M19 21l-7-5-7 5V5a2 2 0 0 1 2-2h10a2 2 0 0 1 2 2z"/>
  </svg>
);

const CLUBS = [
  { id:1, name:'<프로젝트 헤일메리>', time:'12:00 - 01:00', date:'2026.05.13', place:'온라인', current:5, max:10, status:'모집중', liked:false, emoji:'🚀' },
  { id:2, name:'<노르웨이의 숲> 함께 읽어요!', time:'19:00 - 20:30', date:'2026.05.14', place:'서울 마포구', current:3, max:8, status:'모집중', liked:true, emoji:'🌲' },
  { id:3, name:'SF 독서모임 - 듄 시리즈', time:'14:00 - 16:00', date:'2026.05.18', place:'서울 강남구', current:8, max:8, status:'마감', liked:false, emoji:'🪐' },
  { id:4, name:'철학 에세이 읽기 모임', time:'10:00 - 11:30', date:'2026.05.20', place:'온라인', current:4, max:6, status:'모집중', liked:false, emoji:'🧠' },
];

const FILTERS = ['전체', '온라인', '오프라인', '모집중'];

export default function Community() {
  const navigate = useNavigate();
  const [clubs, setClubs] = useState(CLUBS);
  const [filter, setFilter] = useState('전체');

  const filtered = clubs.filter(c => {
    if (filter === '전체') return true;
    if (filter === '온라인') return c.place === '온라인';
    if (filter === '오프라인') return c.place !== '온라인';
    if (filter === '모집중') return c.status === '모집중';
    return true;
  });

  const toggleLike = (id) => {
    setClubs(prev => prev.map(c => c.id === id ? { ...c, liked: !c.liked } : c));
  };

  return (
    <div className="community-page">
      <div className="filter-bar">
        {FILTERS.map(f => (
          <button
            key={f}
            className={`filter-chip${filter === f ? ' active' : ''}`}
            onClick={() => setFilter(f)}
          >
            {f}
          </button>
        ))}
      </div>

      <div className="club-grid">
        {filtered.map(club => (
          <div key={club.id} className="club-card" onClick={() => navigate(`/community/${club.id}`)}>
            <div className="club-card-top">
              <div className="club-avatar">{club.emoji}</div>
              <div className="club-info">
                <div className="club-name">{club.name}</div>
                <div className="club-time">{club.time}</div>
              </div>
              <span className={`club-tag ${club.status === '모집중' ? 'recruiting' : 'full'}`}>
                {club.status}
              </span>
            </div>
            <div className="club-card-bottom">
              <span className="club-meta">{club.date} · {club.place}</span>
              <div className="club-actions">
                <button className={`action-btn${club.liked ? ' liked' : ''}`}
                  onClick={e => { e.stopPropagation(); toggleLike(club.id); }}>
                  <HeartIcon filled={club.liked} />
                </button>
                <button className="action-btn" onClick={e => e.stopPropagation()}>
                  <BookmarkIcon />
                </button>
                <span className="member-count">{club.current}/{club.max}</span>
              </div>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}
